    pub(crate) async fn set_cancel_on_disconnect(&self, request: Option<Input>) -> Result<Output> {
        let request: v::SetCancelOnDisconnectRequest = input(request)?;
        let mut guard = self.acquire()?;
        self.run(async move {
            match &mut *guard {
                NativeSession::Public(_session) => Err(errors::AuthenticationError::new_err(
                    "private RPC method requires authenticated session",
                )),
                NativeSession::Authenticated(session) => session
                    .set_cancel_on_disconnect(request)
                    .await
                    .map_err(native),
            }
        })
        .await
    }
